import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        for (int i = 0; i < n; i++) {
            String nom = in.next();
            String[] yorliqlar = nom.split("\\.");
            System.out.println(yorliqlar.length + " " + yorliqlar[0] + " "
                    + yorliqlar[yorliqlar.length - 2] + "." + yorliqlar[yorliqlar.length - 1]);
        }
    }
}

