#include <iostream>
#include <string>
#include <vector>
using namespace std;

int main() {
    int n;
    cin >> n;
    while (n--) {
        string nom;
        cin >> nom;
        vector<string> yorliqlar;
        size_t boshi = 0;
        while (true) {
            size_t nuqta = nom.find('.', boshi);
            yorliqlar.push_back(nom.substr(boshi, nuqta == string::npos ? string::npos : nuqta - boshi));
            if (nuqta == string::npos) break;
            boshi = nuqta + 1;
        }
        string domen = yorliqlar[yorliqlar.size() - 2] + "." + yorliqlar[yorliqlar.size() - 1];
        cout << yorliqlar.size() << " " << yorliqlar[0] << " " << domen << endl;
    }
    return 0;
}

